def fill_slugs(apps, schema_editor):
    """Atividades que já existiam ganham o endereço amigável a partir do título."""
    from django.utils.text import slugify

    Activity = apps.get_model('activities', 'Activity')
    used = set()
    for activity in Activity.objects.order_by('id'):
        base = slugify(activity.title)[:76].strip('-') or 'atividade'
        slug, n = base, 2
        while slug in used:
            slug, n = f'{base}-{n}', n + 1
        used.add(slug)
        activity.slug = slug
        activity.save(update_fields=['slug'])


